!function(e){function t(t){for(var i,a,o=t[0],d=t[1],m=t[2],c=0,f=[];c<o.length;c++)a=o[c],Object.prototype.hasOwnProperty.call(n,a)&&n[a]&&f.push(n[a][0]),n[a]=0;for(i in d)Object.prototype.hasOwnProperty.call(d,i)&&(e[i]=d[i]);for(s&&s(t);f.length;)f.shift()();return p.push.apply(p,m||[]),r()}function r(){for(var e,t=0;t<p.length;t++){for(var r,a=p[t],o=!0,d=1;d<a.length;d++)r=a[d],0!==n[r]&&(o=!1);o&&(p.splice(t--,1),e=i(i.s=a[0]))}return e}function i(t){if(a[t])return a[t].exports;var r=a[t]={i:t,l:!1,exports:{}};return e[t].call(r.exports,r,r.exports,i),r.l=!0,r.exports}var a={},n={20:0},p=[];i.m=e,i.c=a,i.d=function(e,t,r){i.o(e,t)||Object.defineProperty(e,t,{enumerable:!0,get:r})},i.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},i.t=function(e,t){if(1&t&&(e=i(e)),8&t)return e;if(4&t&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(i.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&t&&"string"!=typeof e)for(var a in e)i.d(r,a,function(t){return e[t]}.bind(null,a));return r},i.n=function(e){var t=e&&e.__esModule?function(){return e.default}:function(){return e};return i.d(t,"a",t),t},i.o=function(e,t){return Object.prototype.hasOwnProperty.call(e,t)},i.p="";var o=window.webpackJsonp=window.webpackJsonp||[],d=o.push.bind(o);o.push=t,o=o.slice();for(var m=0;m<o.length;m++)t(o[m]);var s=d;p.push([88,0]),r()}({88:function(e,t,r){"use strict";r.r(t);var i=r(0);Object(i.a)("de","army",r(89),r(1))},89:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"半履带装甲车辆","link":"de_army#de_army_avhtv"}],"model":"251/9型半履带装甲炮车<br>（75mm突击炮车）","description":"<p>251/9半履带装甲炮车是用251系列中的C型和D型车体改装，安装有一门Kwk 37型24倍口径75mm短管火炮。由于装甲薄弱，因此该型炮车不适用于直接与坦克交战，虽然该型炮车也可以摧毁轻型坦克与装甲车，但主要作用还是为步兵进攻提供直接的火力支援，其较高的射击准确性能在战场上有效地摧毁对方的碉堡、建筑物和地面火炮，故称之为突击炮车。</p><p>1942年，经过德军在东线战场上对251/9半履带装甲炮车样车的实战测试，确认战效理想，于是就马上投入量产，先选用251的C型车进行改装，1943年秋季开始改用251的D型车改装。该型炮车数量较多，先后装备了德国陆军和党卫军的多个装甲师，在二战中、后期的东、西线战场上均可见其身影，一直坚持战斗到二战结束。</p>","part1title":"","part1description":"","part1content":[{"image":"{{text}}D型车体四视图{{image}}imgs/de/army/de_army_avhtv2519_11.jpg","description":"<h6>251/9型半履带装甲炮车（D型车体）<br>（Sd Kfz 251/9 Ausf D）</h6><p>该型炮车核载人员4人：1名驾驶员，1名车长（兼通讯），1 名炮手和1名弹药装填手。</p><p>车上安装一门Kwk 37型24倍口径75mm短管火炮（炮弹52发）和2挺MG34或MG42机枪（子弹2010发）。火炮旋转角度早期：左10°~右12°、上20°~下5°；后期：左右各20°、上16°~下10°。</p>","caption":""},{"image":"{{text}}C型车体{{image}}imgs/de/army/de_army_avhtv2519_12.jpg","description":"<h6>251/9型半履带装甲炮车（C型车体）<br>（Sd Kfz 251/9 Ausf C）</h6><p>前期C型炮车与后期D型炮车的外形区别：<ol><li>前期炮车无安装前置机枪。</li><li>后期炮车的火炮炮架比前期要高大。</li><li>两型车车体侧的储物箱位置有所不同。</li></ol></p>","caption":""}],"part2title":"战场上的251/9型半履带装甲炮车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_avhtv2519_21.jpg","description":"1942年秋天，东线苏联战场高加索地区，隶属德国武装党卫军第5“维京”装甲师的一辆Sd Kfz 251/9 Ausf C型半履带装甲炮车，此车应该是最早出厂的二辆样车中的一辆，该样车出厂后即送到苏联战场上进行测试。","caption":""},{"image":"imgs/de/army/de_army_avhtv2519_22.jpg","description":"1943年7~8月间，东线苏联战场库尔斯克地区，德军一辆不明单位的Sd Kfz 251/9 Ausf D型半履带装甲炮车。由于该型车装甲薄弱，所以没有直接参加坦克大会战，只是执行德军部队的行进掩护、步兵进攻的火力支援、巡逻侦察等任务。","caption":""},{"image":"imgs/de/army/de_army_avhtv2519_23.jpg","description":"1944年8月，西线战场法国地区，隶属德军第2装甲师第304装甲掷弹兵团的一辆Sd Kfz 251/9 Ausf D半履带装甲炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2519_24.jpg","description":"1944年12月，西线战场阿登地区，隶属德国武装党卫军第1“阿道夫·希特勒警卫旗队”装甲师的一辆Sd Kfz 251/9 Ausf D型半履带装甲炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2519_25.jpg","description":"1944年夏天，东线战场波兰地区，隶属德国武装党卫军第5“维京”装甲师第9装甲掷弹兵团的一辆Sd Kfz 251/9 Ausf D型半履带装甲炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2519_26.jpg","description":"1945年3月，德国东普鲁士地区，隶属德军第5装甲师第31装甲团的一辆Sd Kfz 251/9 Ausf D型半履带装甲炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2519_27.jpg","description":"1943年7~8月间，东线苏联战场库尔斯克地区，德军一辆Sd Kfz 251/9 Ausf C型半履带装甲炮车停在阵地上准备向苏军目标射击。","caption":""},{"image":"imgs/de/army/de_army_avhtv2519_28.jpg","description":"1943年7~8月间，东线苏联战场库尔斯克地区，德军一辆Sd Kfz 251/9 Ausf C型半履带装甲炮车的车组成员正在战斗间隙中对炮管进行清洗。","caption":""},{"image":"imgs/de/army/de_army_avhtv2519_29.jpg","description":"1943年底，东线苏联战场，在德军师属榴弹炮阵地上，一辆Sd Kfz 251/9 Ausf C型半履带装甲炮车与105mm榴弹炮一起执行火力支援任务。","caption":""},{"image":"imgs/de/army/de_army_avhtv2519_30.jpg","description":"德军一辆Sd Kfz 251/9 Ausf D型半履带装甲炮车随德军部队一起向前线进发。","caption":""},{"image":"imgs/de/army/de_army_avhtv2519_31.jpg","description":"德军一辆行进中的Sd Kfz 251/9 Ausf D型半履带装甲炮车，炮车车身上已用树枝作了伪装，以防敌方飞机突袭。","caption":""},{"image":"imgs/de/army/de_army_avhtv2519_32.jpg","description":"德军Sd Kfz 251/9 半履带装甲炮车的Kwk 37型24倍口径75mm短管火炮管近照，炮手拟作射击准备。","caption":""},{"image":"imgs/de/army/de_army_avhtv2519_33.jpg","description":"在东线苏联战场上被苏军击毁的德军一辆Sd Kfz 251/9 Ausf D型半履带装甲炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2519_34.jpg","description":"在西线战场上被美军缴获的德军一辆Sd Kfz 251/9 Ausf D型半履带装甲炮车，一名美军在车上检查火炮的状况。","caption":""}]}')}});